body:
This reproduces on master with the following script:
```
PUT my_index
{
  "mappings": {
    "my_parent": {},
    "my_child": {
      "_parent": {
        "type": "my_parent" 
      }
    }
  }
}

PUT my_index/my_parent/1 
{
  "text": "This is a parent document"
}

PUT my_index/my_child/2?parent=1 
{
  "text": "This is a child document"
}

PUT my_index/my_child/3?parent=1&refresh=true 
{
  "text": "This is another child document"
}


PUT my_index/my_parent/4
{
  "text": "This is a parent document"
}

PUT my_index/my_child/5?parent=4
{
  "text": "This is a child document"
}

PUT my_index/my_child/6?parent=4&refresh=true 
{
  "text": "This is another child document"
}

# Works and returns hits
GET my_index/_search
{
  "query":{
    "more_like_this":{
      "fields":[
        "text"
      ],
      "like":[
        {
          "_index":"my_index",
          "_type":"my_parent",
          "_id":"1"
        }
      ],
      "min_term_freq":1,
      "min_doc_freq":1
    }
  }
}

# Returns 0 hits
GET my_index/_search
{
  "query":{
    "more_like_this":{
      "fields":[
        "text"
      ],
      "like":[
        {
          "_index":"my_index",
          "_type":"my_child",
          "_id":"2"
        }
      ],
      "min_term_freq":1,
      "min_doc_freq":1
    }
  }
}
```
Even if you specify the `_routing` using the parent's id it still returns 0 hits:

```
# Returns 0 hits
GET my_index/_search
{
  "query":{
    "more_like_this":{
      "fields":[
        "text"
      ],
      "like":[
        {
          "_index":"my_index",
          "_type":"my_child",
          "_id":"2",
          "_routing": "1"
        }
      ],
      "min_term_freq":1,
      "min_doc_freq":1
    }
  }
}
```
